        let _this = this;

        if (_this.isTabMode) {
            _this.subscriptions.push(_this._navigationService.onBottomTabRefreshRequested.subscribe((value) => {
                if (_this.isCurTab) {
                    _this.loadData();
                }
            }));
        }
