        this.showAdvSearch = false;

        this.viewKeys = null;
        this.completeSearchKeys = null;
        this.advancedSearchKeys = null;
        // this.searchToggles = null;
        this.displayedColumns = null;
        this.currentKeys = null;

        this.searchOptions = null;
        this.searchData = null;
