    loadTable(search_keys: any): void {
        const _this = this;
        _this.isLoading = true;
        _this.hasData = false;

        // Add search toggles if exist
        search_keys = _this.applySearchToggles(search_keys);
        search_keys = _this.applyHomepageKeys(search_keys);

        _this.subscriptions.push(_this.backendService.getData(_this.tableData.entryName, _this.authService.getCurrentCompany(_this.currentKeys), _this.currentKeys, search_keys, false, false, null, false).subscribe(
            results => {
                _this._console.log(results);
                if (results.result === 'OK') {
                    _this.showAdvSearch = false;
                    results = results.data;

                    if(results['styleQueries']) {
                        _this.styleQueries = results['styleQueries'];
                        _this.loadStyle(_this.viewKeys);
                    }

                    if (results.search_options) { // got some search combobox options
                        _this.searchOptions = results.search_options; // store them
                        results = results.table_data; // and get the table data
                    }
                    _this.searchData = _this.getSearchData(_this.advancedSearchKeys);
                    if (_this.showExplorer) {
                        _this.loadExplorerData(results);
                    }

                const visibleKeys = _this.viewKeys.filter(x => !x.isHidden).map(x => x.key); 
                _this.dataSource = new MatTableDataSource(results);

                _this.dataSource.filterPredicate = function(data, filter: string): boolean {
                    let value = false;
                    visibleKeys.forEach(visibleKey => {
                        if(data[visibleKey] && data[visibleKey].toString().toLowerCase().includes(filter.toLowerCase()))
                        {
                            value = true;
                            return;  
                        }
                    });
                    return value;
                  };
                    _this.dataSource.sort = _this.sort;
                    if (_this.paginator) {
                        _this.dataSource.paginator = _this.paginator;
                    }
                    _this.loadTotalRow();
                    //_this.adjustViewKeysWidths();
                    _this.autodetectViewMode();
                    // triggers any change in displayed datasource, setting the array of primary keys
                    _this.subscriptions.push(_this.dataSource.connect().subscribe(source => {
                        _this.keysArray = source.map(row => {
                            const key_values = {};
                            const primaryKeys = _this.viewKeys.filter(entry => {
                                return entry.isPrimary;
                            });
                            for (const primaryKey of primaryKeys) {
                                key_values[primaryKey.key] = row[primaryKey.key];
                            }
                            return key_values;
                        });
                    }));
                    _this.hasData = results && results.length > 0;
                    _this.changeDetector.detectChanges();
                    _this.isLoading = false;
                }
                else {
                    if (results.reason === 'Not Authorized') {
                        _this._console.log('Not Authorized');
                        _this.isAuthorized = false;
                    }
                    else {
                        // Show error snackbar
                        _this._toastService.showErrorToast("Error ", JSON.stringify(results.reason.detail));
                    }
                }

                _this.isLoading = false;
            },
            error => {
                _this.isLoading = false;
                _this._toastService.showErrorToast("Error ", JSON.stringify(error));
            }));

        // Calculate table height
        this.calculateTableHeight();
    }

    adjustViewKeysWidths() {
        let _this = this;
        const sum = _this.viewKeys.filter(x => !x.isHidden && x.width).map(x => parseFloat(x.width.replace('%', ''))).reduce((sum, n) => sum + n);

        _this.viewKeys.forEach((x, i) => {
            if (_this.viewKeys[i].width) {
                const width = (parseFloat(x.width.replace('%', '')) / (sum / 100)) + '%';
                _this.viewKeys[i].width = width;
            }
        })
    }

    autodetectViewMode() {
        let _this = this;
        const sum = _this.viewKeys.filter(x => !x.isHidden && x.width).map(x => parseFloat(x.width.replace('%', ''))).reduce((sum, n) => sum + n , 0);
        _this.wrapView = sum <= 100;
    }

    loadTotalRow() {

        let _this = this;
        const totalKeys = _this.viewKeys.filter(x => x.showTotal).map(x => x.key);
        if (totalKeys && totalKeys.length > 0) {
            let totalRow = {};

            let dataToProcess = _this.dataSource.data;

            if(_this.paginator) {
                const skip = _this.paginator.pageSize * _this.paginator.pageIndex;
                dataToProcess = _this.dataSource.sortData(_this.dataSource.filteredData, _this.dataSource.sort).filter((u, i) => i >= skip)
                .filter((u: any, i: number) => i < _this.paginator.pageSize);
            }

            totalKeys.forEach(key => {
                totalRow[key] = (dataToProcess.map(x => parseFloat(x[key] + '')).reduce((partialSum, a) => partialSum + a, 0)) + '';
            });
            _this.totalRow = totalRow;
        }
        else {
            _this.totalRow = null;
        }
    }

    loadLevel(table_keys) {
        this.isLevel = null;
        this.hasLevel = null;

        table_keys.forEach(key => {
            if (key.isLevel) {
                if (!this.isLevel) {
                    this.isLevel = key.key;
                }
                else {
                    this._console.error('More than one isLevel key defined!');
                }
            }
            else if (key.hasLevel) {
                if (!this.hasLevel) {
                    this.hasLevel = [];
                }
                this.hasLevel.push(key.key);
            }
        });

        this._console.log('isLevel', this.isLevel);
        this._console.log('hasLevel', this.hasLevel);
    }

    loadFormat(table_keys: TableViewKey[]) {
        if (table_keys && table_keys.length) {
            this.format = {};
            table_keys.forEach(viewKey => {
                this.format[viewKey.key] = {
                    dataType: viewKey.format.dataType,
                    pipe: viewKey.format.pipe
                }
            })
        }
    }

    loadAddElementSettings(addElementSettings: AddElementSettings) {
        this.addElementSettings = addElementSettings;
        if(this.addElementSettings) {
            this.addElementSettings.labelQuickAdd = this.addElementSettings.labelQuickAdd ?? "Quick Add";
            this.addElementSettings.labelAdd = this.addElementSettings.labelAdd ?? "Add Element";

            this.addElementLabel = {
                label: this.addElementSettings.labelAdd,
                translate: this.addElementSettings.translateAdd
            }

            this.quickAddLabel = {
                label: this.addElementSettings.labelQuickAdd,
                translate: this.addElementSettings.translateQuickAdd
            }
        }
        else {
            this.addElementLabel = {
                label: "Add Element",
                translate: null
            }

            this.quickAddLabel = {
                label: "Quick Add",
                translate: null
            }
        }
    }

    getLevel(row, key) {
        if (this.isLevel == key || (this.hasLevel && this.hasLevel.includes(key))) {
            let text = row[this.isLevel] ? row[this.isLevel].split(this.levelIndentationMarker) : null;
            return text ? (text.length - 1) * this.levelIndentationValue : this.levelIndentationValue;
        }
        else {
            return 0;
        }
    }

    loadStyle(table_keys) {
        let _this = this;
        _this.styles = {};
        table_keys.forEach(key => {
            if (_this.styleQueries && _this.styleQueries[key.key]) {
                if (!_this.styles[key.key]) {
                    _this.styles[key.key] = [];
                }
                Object.keys(_this.styleQueries[key.key]) .forEach(s => {
                    (_this.styles[key.key] as TableStyleElement[]).push({value: s, condition: "==", style: _this.styleQueries[key.key][s][0]});
                });
            }
            if (key.style && key.style.length) {
                key.style.forEach(style => {
                    if (!_this.styles[key.key]) {
                        _this.styles[key.key] = [];
                    }
                    (_this.styles[key.key] as TableStyleElement[]).push({value: style.value, valueKey: style.valueKey, condition: style.condition ?? "==", style: style});
                });
            }
        });
    }

    doesButtonIconExist(key: string) {
        let buttonIconExists = false;
        if (this.styles && this.styles[key]) {
            const keys = (this.styles[key] as TableStyleElement[]).map(x => x.value);

            keys.forEach(k => {
                if((this.styles[key] as TableStyleElement[]).some(x => x.value === k && x.style['button_icon'])) {
                    buttonIconExists = true;
                }
                // if (this.styles[key][k]['button_icon']) {
                //     buttonIconExists = true;
                // }
            })
        }
        return buttonIconExists;
    }

    getButtonIcon(key: string, value: string) {
        let style: any = {};
        if(Array.isArray(this.styles[key])) {
            const valuedStyle = [
                ...(this.styles[key] as TableStyleElement[]).filter(x => x.value === value),
                ...(this.styles[key] as TableStyleElement[]).filter(x => x.value === "*"),
            ];

            if(valuedStyle.length > 0) {
                style = valuedStyle[0].style;
            } 
        }
        else {
            style = this.styles[key];
        }
        return style['button_icon'];
    }

    getElementStyle(column, value, row) {
        let styles = {};
        const styleKeysToIgnore = ['condition', 'value', 'button_icon'];

        const valueStr = value != null ? value + '' : null;
        if (column && valueStr && this.styles[column]) {
            const columnStyles = this.styles[column];
            styles = HelperService.getStyleByValue(valueStr, columnStyles, row, styleKeysToIgnore);

        }
        return styles;
    }

    private loadRestrictions(restrictions: Restrictions) {
        if (restrictions && Object.keys(restrictions).length > 0) {
            this.restrictions = restrictions;
        }
        else {
            this.restrictions = {
                preventNavigationToForm: false
            };
        }
    }

    private loadSelectionActions(actions: SelectionAction[]) {
        if (actions && actions.length) {
            this.selectionActions = actions.map(x => {
                return {
                    viewType: x.viewType,
                    key: x.key,
                    label: x.label,
                    icon: x.icon,
                    menuOptions: x.menuOptions,
                    confirmAction: x.confirmAction,
                    reloadOnSuccess: x.reloadOnSuccess,
                    confirmActionMessage: x.confirmActionMessage
                }
            });
        }
        else {
            this.selectionActions = null;
        }
    }

    private loadViewKeys(table_keys: any[]) {
        if (this.selectionActions && this.selectionActions.length) {
            let selectTableKey: TableViewKey = {
                format: { dataType: 'checkbox' },
                isHidden: false,
                isPrimary: false,
                isSelectCheckbox: true,
                key: 'selectCheckbox',
                label: 'Select Checkbox',
            };
            this.viewKeys = [selectTableKey].concat(table_keys);
        }
        else {
            this.viewKeys = table_keys;
        }
    }

    private getSearchData(searchKeys: SearchViewKey[]): FieldConfig[] {
        let _this = this;
        let fieldValues: FieldConfig[] = [];

        if (!searchKeys) {
            return fieldValues;
        }

        searchKeys.forEach(field => {
            let fieldValue: FieldConfig;
            let searchEntry = _this.searchOptions ? _this.searchOptions.find(e => e.fieldName === field.fieldName) : null;
            let options = [];
            if (searchEntry) {
                options = searchEntry.options;
            }
            fieldValue = {
                label: field.label,
                translate: field.translate,
                tooltip: field.tooltip,
                name: field.fieldName,
                value: null,
                type: field.format.viewType,
                inputType: field.format.dataType ? field.format.dataType : '',
                newLine: field.newLine !== null ? field.newLine : true,
                options: options,
                validations: [],
                isVisible: true,
                width: (field.size != null) ? (field.size * 10) : null, // leave a 0.5% margin left and right   
            };
            fieldValues.push(fieldValue);
        });

        _this.process_form_row(fieldValues, _this.margins);
        return fieldValues;

    }

    advSearch() {
        if (!this.searchKeysLoaded) {
            this.loadSearchKeys();
        }
        else {
            this.showAdvSearch = !this.showAdvSearch;
        }
    }

    updateAdvancedSearchKeys(searchKeys: SearchViewKey[]) {
        if (searchKeys && searchKeys.length > 0) {
            this.advancedSearchKeys = searchKeys.filter(x => x.format.viewType != 'toggle');
        }
        else {
            this.advancedSearchKeys = [];
        }
    }

    loadSearchToggles(completeSearchKeys: SearchViewKey[], searchKeys: any = null) {
        if (completeSearchKeys && completeSearchKeys.length > 0) {
            this.searchToggles = completeSearchKeys.filter(x => x.format.viewType == 'toggle').map(x => {
                let checked = false;
                if (searchKeys && Object.keys(searchKeys).includes(x.fieldName)) {
                    checked = searchKeys[x.fieldName];
                }
                else {
                    checked = (x.format.value == 'true' || x.format.value == true || x.format.value == '1' || x.format.value == 1) ? true : false;
                }
                return {
                    fieldName: x.fieldName,
                    label: x.label,
                    translate: x.translate,
                    tooltip: x.tooltip,
                    checked: checked
                };
            });

            this.searchToggles;
        }
        else {
            this.searchToggles = [];
        }
    }

