export class ChallengeNameType {
  public static readonly ADMIN_NO_SRP_AUTH = "ADMIN_NO_SRP_AUTH";
  public static readonly CUSTOM_CHALLENGE = "CUSTOM_CHALLENGE";
  public static readonly DEVICE_PASSWORD_VERIFIER = "DEVICE_PASSWORD_VERIFIER";
  public static readonly DEVICE_SRP_AUTH = "DEVICE_SRP_AUTH";
  public static readonly MFA_SETUP = "MFA_SETUP";
  public static readonly NEW_PASSWORD_REQUIRED = "NEW_PASSWORD_REQUIRED";
  public static readonly PASSWORD_VERIFIER = "PASSWORD_VERIFIER";
  public static readonly SELECT_MFA_TYPE = "SELECT_MFA_TYPE";
  public static readonly SMS_MFA = "SMS_MFA";
  public static readonly SOFTWARE_TOKEN_MFA = "SOFTWARE_TOKEN_MFA";
};

const appData = (environment.appData as any).default;
@Injectable({
  providedIn: "root",
})
export class AuthService {
  private username: string;
  private password: string;
  private email: string;
  private code: string;
  errorMessage: string;
  public isSignedIn = false;

  // backend user data
  public userinfo = new BehaviorSubject<UserInfo>({
    name: null,
    lastname: null,
    username: null,
    picture: null,
    language: "it",
    companies: [],
    allowedToInvite: false,
    onekyc: false,
    sync: null,
    timereport: false
  });

  // Error Information Event Emitter for catching and emitting
  // Login and Signup related errors.
  // public errorInfo$ = new EventEmitter<any>();
  public isCheckingExpiry: boolean;
  public interval;
  private currentCompany: string;
  private confirmUser: any;
  private sync: any;
  private timereport: boolean;
  private tables: any;
  private onekyc: boolean;
  private allowedToInvite: boolean;

  // Google
  // googleUser: SocialUser;
  // googleUserLoggedIn: boolean;

  googleScopes = {
    gdrive: "https://www.googleapis.com/auth/drive https://www.googleapis.com/auth/drive.metadata.readonly https://www.googleapis.com/auth/drive.file",
    gmail: "https://www.googleapis.com/auth/gmail.readonly", //"https://mail.google.com"
  };

  constructor(
    private awsService: AwsService,
    private amplifyService: AmplifyService,
    private backendService: BackendService,
    private navigationService: FuseNavigationService,
    private _toastService: ToastService,
    private _fuseTranslationLoaderService: FuseTranslationLoaderService,
    private _translateService: TranslateService,
    private _console: ConsoleLoggerService
  ) {
    this.awsService = awsService;

    this.awsService.auth();

    this.initGoogleOAuth();

    this.awsService.errorInfo$
      .subscribe(error => {

        this._setError(error);
      }, (err) => {
        // Error occured!
        this._setError(err);
      });



  }

  get authStateChange$(): BehaviorSubject<OCAuthState> | null {
    return this.awsService.authStateChange$;
  }

  get errorInfo$(): BehaviorSubject<any> | null {
    return this.awsService.errorInfo$;
  }

  public setUsername(username: string): void {
    this.username = username;
  }

  public getUsername(): string {
    return this.username;
  }

  public setPassword(password: string): void {
    this.password = password;
  }

  public setEmail(email: string): void {
    this.email = email;
  }

  public setCode(code: string): void {
    this.code = code;
  }

  public getCode(): string {
    return this.code;
  }

  public getEmail(): string {
    return this.email;
  }

  public async forgotPassword(username: string) {
    let _this = this;
    let result = await _this.backendService.forgotPassword(username).toPromise();
    if (result && result.result === "OK") {
    } else {
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
  }

  public async forgotPasswordSubmit(username: string, code: string, new_password: string) {
    let _this = this;
    let result = await _this.backendService.confirmForgotPassword(username, code, new_password).toPromise();
    if (result && result.result === "OK") { 
      let authState: OCAuthState = {
        session: null,
        state: null,
        user: null,
      };
      _this.authStateChange$.next(authState);

    } else {
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
  }

  /** change password */
  public async changePassword(newPassword: string) {
    const _this = this;   
    const session = _this.authStateChange$.value.session;

    let result = await _this.backendService.changePassword(session.ChallengeParameters.USER_ID_FOR_SRP, session.Session, newPassword, ChallengeNameType.NEW_PASSWORD_REQUIRED).toPromise();
    if (result && result.result === "OK") {
      if (result.data["ChallengeName"] ===  ChallengeNameType.NEW_PASSWORD_REQUIRED) {
        _this.awsService.setAuthState({
            state: "requireNewPassword",
            user: result,
        });
      } else {
        _this.awsService.auth().loadSignInResponse(result.data);
        return true;
      }
    } else {  
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
  }

  /** signin */
  public async signIn(){
    const _this = this;
    let result = await _this.backendService.signIn(_this.username, _this.password).toPromise();
    if (result && result.result === "OK") {
      let user = result.data; 
      let challengeName = user.ChallengeName;
      if (challengeName === ChallengeNameType.SOFTWARE_TOKEN_MFA || challengeName === ChallengeNameType.SMS_MFA) {
        _this.confirmUser = user;
        _this.awsService.auth().mfa = challengeName;
        _this.awsService.setAuthState({
          state: "confirmSignIn",
          user: user,
        });
      } else if (challengeName && challengeName ===  ChallengeNameType.NEW_PASSWORD_REQUIRED) {
        _this.awsService.setAuthState({
          state: "requireNewPassword",      
          session: user,
        });
      } else {
        _this.awsService.auth().loadSignInResponse(user);
        // now get user and related menu info from backend
        if (user) {
          _this.isSignedIn = true; 
          _this.retrieveUserInfo();
        }
      }
    } else {  
      if (result?.reason === 'PasswordResetRequiredException') {
        _this.awsService.setAuthState({

          state: "forgotPassword",
          session: null,
          user: null
        }); 
      }
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
  }

  public signOut(): void {
    this.isSignedIn = false;
    this.currentCompany = null; // force default company for next login
    this.awsService.auth().mfa = "";
    this.awsService.auth().signOut();
    if (this.interval) {
      clearInterval(this.interval);
    }

    localStorage.clear();
    this.userinfo.next({
      name: null,
      lastname: null,
      username: null,
      picture: null,
      language: "it",
      companies: [],
      allowedToInvite: false,
      onekyc: false,
      sync: null,
      timereport: false
    }); // user data nulled
    // reset the left menu
    this.navigationService.setCurrentNavigation("main");
    this.navigationService.unregister("usermenu");
    this.signOutGoogle();
  }

  public async signUp(isInvitedUser: boolean = false) {
    let _this = this;
    let result = await _this.backendService.signUp(_this.username, _this.password, _this.email).toPromise();
    if (result && result.result === "OK") { 
      if (!isInvitedUser) {
        _this.awsService.setAuthState({
            state: "sign-up",
            user: result.data,
        });
      }
      return result.data;
    } else {
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
  }

  public async confirmSignUp(code: string) {
    let _this = this;
    let result = await _this.backendService.confirmSignUp(_this.username, code).toPromise();
    if (result && result.result === "OK") { 
      _this.awsService.setAuthState({
        state: "confirm-sign-up",
        user: { username: _this.username },
      });
    } else {
      _this.errorInfo$.next(result?.reason);
      _this._setError(result?.reason);
    }
    // this.awsService
    //   .auth()
    //   .confirmSignUp(this.username, code)
    //   .then((data) => {
    //     this.awsService.setAuthState({
    //       state: "confirm-sign-up",
    //       user: { username: this.username },
    //     });
    //     this._console.log(data);
    //   })
    //   .catch((err) => {
    //     this._setError(err);
    //   });
  }

  public updateUserInfo(company: string): void {
    const _this = this;
    if (company == null || company === _this.currentCompany) {
      return;
    }
    _this.currentCompany = company;
    // Save company to local storage
    _this.setLastCompany(_this.currentCompany);
    // reset the left menu
    _this.navigationService.setCurrentNavigation("main");
    _this.navigationService.unregister("usermenu");

    //get languages
    _this.retrieveLanguages();

    // get new menu
    _this.retrieveMenu();
  }
  public updateUserLanguage(language: string): void {
    const _this = this;

    _this.setLastLanguage(language);
    //get languages
    _this.retrieveLanguages();

    // get new menu
    _this.retrieveMenu();
  }

  public getCurrentCompany(currentKeys: any = null): string {
    const _this = this;
    if (currentKeys != null && currentKeys.codice_azienda != null) {
      return currentKeys.codice_azienda;
    }
    return _this.currentCompany;
  }

  _setError(err): void {
    if (!err) {
      this.errorMessage = null;
      return;
    }

    this.errorMessage = err.message || err;
  }

  public setUserMFA(mfa) {
    this.awsService.auth().setUserMFA(mfa);
  }

  public async retrieveUserInfo(forced: boolean = false) {
    const _this = this;
    //  _this.interval = setInterval(
    //     () => _this.awsService.auth().refreshToken(),
    //     1000
    //   );

    await _this.awsService.auth().refreshToken(forced);
    _this.backendService.getUserData().subscribe((ud) => {
      if (ud != null && ud.result === "OK") {
        if (ud.userdata.language == null) {
          ud.userdata.language = "it"; // defaults to italian
        } else {
          let lastLanguage: string = _this.getLastLanguage();
          if (lastLanguage) {
            ud.userdata.language = lastLanguage;
          }
        }
        _this.userinfo.next(ud.userdata); // signal a value change to subscribers
        if (_this.currentCompany == null) {
          // do not get default company if reloading because of user chose a different company
          // Check if last company is stored in local storage
          let lastCompany: string = _this.getLastCompany();
          if (
            lastCompany &&
            ud.userdata.companies.includes(lastCompany)
          ) {
            // Set last company from local storage
            _this.currentCompany = lastCompany;
          } else {
            // Select first compnay from companies list
            _this.currentCompany = ud.userdata.companies[0];
            // Save company to local storage
            _this.setLastCompany(_this.currentCompany);
          }
        }
        _this.sync = ud.userdata.sync || null;

        // If sync mode is google then signin
        // if(_this.sync === 'google') {
        //   _this.loginGoogle('gdrive');
        // }

        _this.onekyc = ud.userdata.onekyc;

        _this.timereport = ud.userdata.timereport;

        _this.tables = ud.userdata.tables;

        _this.allowedToInvite = ud.userdata.allowedToInvite;

        _this._console.log(ud.userdata);

        //load default language for user
        _this._translateService.setDefaultLang(ud.userdata.language);

        //get languages
        _this.retrieveLanguages();

        // get new menu
        _this.retrieveMenu();
      } else {
        // Show error snackbar
        _this._toastService.showErrorToast(ud?.reason ?? ud);
        _this.userinfo.next(null);
        _this._console.error(ud);
      }
    });
  }

