import { Injectable } from '@angular/core';
import { Action, Store } from '@ngrx/store';
import { Actions, createEffect, ofType } from '@ngrx/effects';

import { Observable, of, forkJoin } from 'rxjs';
import { catchError, debounceTime, map, mergeMap, exhaustMap, withLatestFrom } from 'rxjs/operators';

import { getRouterState, State } from 'app/store/reducers';
import { getMailsState } from 'app/main/apps/mail-ngrx/store/selectors';
import * as MailsActions from 'app/main/apps/mail-ngrx/store/actions/mails.actions';
import * as fromRoot from 'app/store';

import { Mail } from 'app/main/apps/mail-ngrx/mail.model';
import { MailNgrxService } from 'app/main/apps/mail-ngrx/mail.service';

@Injectable()
export class MailsEffect {
    routerState: any;

    constructor(
        private actions: Actions,
        private mailService: MailNgrxService,
        private store: Store<State>
    ) {
        this.store.select(getRouterState).subscribe(routerState => {
            if (routerState) {
                this.routerState = routerState.state;
            }
        });
    }

    /**
     * Get Mails with router parameters
     * @type {Observable<any>}
     */
    getMails: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.GetMails>(MailsActions.GET_MAILS),
                exhaustMap((action) => {

                    let handle = {
                        id: '',
                        value: ''
                    };

                    const routeParams = of('labelHandle', 'filterHandle', 'folderHandle');
                    routeParams.subscribe(param => {
                        if (this.routerState.params[param]) {
                            handle = {
                                id: param,
                                value: this.routerState.params[param]
                            };
                        }
                    });

                    return this.mailService.getMails(handle)
                        .pipe(
                            map((mails: Mail[]) => {

                                return new MailsActions.GetMailsSuccess({
                                    loaded: handle,
                                    mails: mails
                                });
                            }),
                            catchError(err => of(new MailsActions.GetMailsFailed(err)))
                        );
                })
            ));

    /**
     * Update Mail
     * @type {Observable<any>}
     */
    updateMail =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.UpdateMail>(MailsActions.UPDATE_MAIL),
                exhaustMap((action) => {
                    return this.mailService.updateMail(action.payload).pipe(
                        map(() => {
                            return new MailsActions.UpdateMailSuccess(action.payload);
                        })
                    );
                })
            ));

    /**
     * UpdateMails
     * @type {Observable<any>}
     */
    updateMails: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.UpdateMails>(MailsActions.UPDATE_MAILS),
                exhaustMap((action) => {
                    return forkJoin(
                        action.payload.map(mail => this.mailService.updateMail(mail)),
                        () => {
                            return new MailsActions.UpdateMailsSuccess();
                        });
                })
            ));

    /**
     * Set Current Mail
     * @type {Observable<SetCurrentMailSuccess>}
     */
    setCurrentMail: Observable<Action> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.SetCurrentMail>(MailsActions.SET_CURRENT_MAIL),
                withLatestFrom(this.store.select(getMailsState)),
                map(([action, state]) => {
                    return new MailsActions.SetCurrentMailSuccess(state.entities[action.payload]);
                })
            ));

    /**
     * Check Current Mail
     * Navigate to parent directory if not exist in mail list
     * Update Current Mail if exist in mail list
     * @type {Observable<any>}
     */
    checkCurrentMail: Observable<Action> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.CheckCurrentMail>(MailsActions.CHECK_CURRENT_MAIL),
                withLatestFrom(this.store.select(getMailsState)),
                map(([action, state]) => {

                    if (!state.entities[this.routerState.params.mailId]) {
                        return new fromRoot.Go({ path: [this.routerState.url.replace(this.routerState.params.mailId, '')] });
                    }
                    return new MailsActions.SetCurrentMailSuccess(state.entities[this.routerState.params.mailId]);
                })
            ));

    /**
     * On Get Mails Success
     * @type {Observable<CheckCurrentMail>}
     */
    getMailsSuccess: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.GetMailsSuccess>(MailsActions.GET_MAILS_SUCCESS),
                mergeMap(() =>
                    [
                        new MailsActions.CheckCurrentMail()
                    ])
            ));
    /**
     * On Update Mails Success
     * @type {Observable<DeselectAllMails | GetMails>}
     */
    updateMailsSuccess: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.UpdateMailsSuccess>(MailsActions.UPDATE_MAILS_SUCCESS),
                mergeMap(() =>
                    [
                        new MailsActions.DeselectAllMails(),
                        new MailsActions.GetMails()
                    ])
            ));
    /**
     * On Update Mail Success
     * @type {Observable<GetMails>}
     */
    updateMailSuccess: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.UpdateMailSuccess>(MailsActions.UPDATE_MAIL_SUCCESS),
                debounceTime(500),
                map(() => {
                    return new MailsActions.GetMails();
                })
            ));

    /**
     * Set Folder on Selected Mails
     * @type {Observable<UpdateMails>}
     */
    setFolderOnSelectedMails: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.SetFolderOnSelectedMails>(MailsActions.SET_FOLDER_ON_SELECTED_MAILS),
                withLatestFrom(
                    this.store.select(getMailsState)),
                map(([action, state]) => {
                    const entities = { ...state.entities };
                    let mailsToUpdate = [];
                    state.selectedMailIds
                        .map(id => {
                            mailsToUpdate = mailsToUpdate.concat(entities[id] = {
                                ...entities[id],
                                folder: action.payload
                            });
                        });
                    return new MailsActions.UpdateMails(mailsToUpdate);
                })
            ));

    /**
     * Add Label on Selected Mails
     * @type {Observable<UpdateMails>}
     */
    addLabelOnSelectedMails: Observable<MailsActions.MailsActionsAll> =
        createEffect(() => this.actions
            .pipe(
                ofType<MailsActions.AddLabelOnSelectedMails>(MailsActions.ADD_LABEL_ON_SELECTED_MAILS),
                withLatestFrom(this.store.select(getMailsState)),
                map(([action, state]) => {

                    const entities = { ...state.entities };
                    let mailsToUpdate = [];

                    state.selectedMailIds
                        .map(id => {

                            let labels = [].concat(entities[id].labels);

                            if (!entities[id].labels.includes(action.payload)) {
                                labels = labels.concat(action.payload);
                            }

                            mailsToUpdate = mailsToUpdate.concat(
                                entities[id] = {
                                    ...entities[id],
                                    labels
                                }
                            );
                        });

                    return new MailsActions.UpdateMails(mailsToUpdate);
                })
            ));
}

import { Injectable } from '@angular/core';
import { MessageView } from '../interfaces';


@Injectable({
    providedIn: 'root'
})
export class MessagesService {

    /**
     * Constructor
     *
     */
    constructor() {
    }

    /**
         * Get Form Message Views
         * @param messageViews Message Views list
         * @returns Form Message Views
         */
    getFormMessages(messageViews: MessageView[]) {
        if (!messageViews || !messageViews.length) {
            return [];
        }
        return messageViews
            .filter(a => a.viewType === "form")
            .map(a => {
                return {
                    messageType: a.formMessageType,
                    message: a.message
                }
            });
    }

    /**
     * Get Table Message Views
     * @param messageViews Message Views list
     * @returns Table Message Views
     */
    getTableMessages(messageViews: MessageView[]) {
        if (!messageViews || !messageViews.length) {
            return [];
        }
        return messageViews
            .filter(a => a.viewType === "table")
            .map(a => {
                return {
                    messageType: a.tableMessageType,
                    message: a.message
                }
            });
    }
}

import { Injectable, EventEmitter } from '@angular/core';
import { HideAction } from '../interfaces';

@Injectable({
    providedIn: 'root'
})
export class NavigationService {

    /**
     * Constructor
     */
    constructor() {
    }

    //#region Toolbar Hide actions

    // Toolbar Hide actions data
    private _toolbarHideActions: string[] = [];

    // get current data
    public getToolbarHideActions() {
        return this._toolbarHideActions;
    }

    // Event Emitter for hide actions
    public onToolbarHideActionsChanged: EventEmitter<string[]> = new EventEmitter();

    // public onHideActionsUpdated: EventEmitter<HideAction[]> = new EventEmitter();

    // Event Emitter for 
    public onBottomTabRefreshRequested: EventEmitter<boolean> = new EventEmitter();


    public onDashboardTableLoad: EventEmitter<{origin: string, dashboardTables: string[]}> = new EventEmitter();

    /**
     * Update Tooblar Hide Actions
     * @param hideActions Hide Actions
     * @param viewType The parent view containing hide actions
     * @emits onToolbarHideActionsChanged Toolbar hide Actions as string[]
     */
    updateToolbarHideActions(hideActions: string[]) {
        this.onToolbarHideActionsChanged.emit(hideActions);
    }

    //#endregion

    /**
     * Get Form Hide Actions
     * @param hideActions Hide Actions list
     * @returns Form Hide Actions
     */
    getFormHideActions(hideActions: HideAction[]) {
        if (!hideActions || !hideActions.length) {
            return [];
        }
        return hideActions
            .filter(a => a.viewType === "form")
            .map(a => a.formActionType);
    }

    /**
     * Get Table Hide Actions
     * @param hideActions Hide Actions list
     * @returns Table Hide Actions
     */
    getTableHideActions(hideActions: HideAction[]) {
        if (!hideActions || !hideActions.length) {
            return [];
        }
        return hideActions
            .filter(a => a.viewType === "table")
            .map(a => a.tableActionType);
    }

    /**
     * Ruest Bottom tabs refresh
     */
    requestBottomTabRefresh() {
        this.onBottomTabRefreshRequested.emit(true);
    }

}

import {
    Inject,
    Injectable,
    InjectionToken,
    Optional,
    NgModule,
} from "@angular/core";
import { NgxMatDateAdapter } from "@angular-material-components/datetime-picker";
import { MAT_DATE_LOCALE } from "@angular/material/core";

// TODO(mmalerba): See if we can clean this up at some point.
import * as _moment from 'moment';
// tslint:disable-next-line:no-duplicate-imports
// @ts-ignore
import { default as _rollupMoment, Moment, MomentFormatSpecification, MomentInput } from 'moment';


const moment = _moment;

export interface NgxMatMomentDateAdapterOptions {
    strict?: boolean;

    useUtc?: boolean;
}

export const MAT_MOMENT_DATE_ADAPTER_OPTIONS =
    new InjectionToken<NgxMatMomentDateAdapterOptions>(
        "MAT_MOMENT_DATE_ADAPTER_OPTIONS",
        {
            providedIn: "root",
            factory: MAT_MOMENT_DATE_ADAPTER_OPTIONS_FACTORY,
        }
    );

export function MAT_MOMENT_DATE_ADAPTER_OPTIONS_FACTORY(): NgxMatMomentDateAdapterOptions {
    return {
        useUtc: false,
    };
}

function range<T>(length: number, valueFunction: (index: number) => T): T[] {
    const valuesArray = Array(length);
    for (let i = 0; i < length; i++) {
        valuesArray[i] = valueFunction(i);
    }
    return valuesArray;
}

@Injectable()
export class OCDatetimeAdapter extends NgxMatDateAdapter<Moment> {
    private _localeData: {
        firstDayOfWeek: number;
        longMonths: string[];
        shortMonths: string[];
        dates: string[];
        longDaysOfWeek: string[];
        shortDaysOfWeek: string[];
        narrowDaysOfWeek: string[];
    };

    constructor(
        @Optional() @Inject(MAT_DATE_LOCALE) dateLocale: string,
        @Optional()
        @Inject(MAT_MOMENT_DATE_ADAPTER_OPTIONS)
        private _options?: NgxMatMomentDateAdapterOptions
    ) {
        super();
        this.setLocale(dateLocale || moment.locale());
    }

    setLocale(locale: string) {
        super.setLocale(locale);

        const momentLocaleData = moment.localeData(locale);
        this._localeData = {
            firstDayOfWeek: momentLocaleData.firstDayOfWeek(),
            longMonths: momentLocaleData.months(),
            shortMonths: momentLocaleData.monthsShort(),
            dates: range(31, (i) =>
                this.createDate(2017, 0, i + 1).format("D")
            ),
            longDaysOfWeek: momentLocaleData.weekdays(),
            shortDaysOfWeek: momentLocaleData.weekdaysShort(),
            narrowDaysOfWeek: momentLocaleData.weekdaysMin(),
        };
    }

    getYear(date: Moment): number {
        return this.clone(date).year();
    }

    getMonth(date: Moment): number {
        return this.clone(date).month();
    }

    getDate(date: Moment): number {
        return this.clone(date).date();
    }

    getDayOfWeek(date: Moment): number {
        return this.clone(date).day();
    }

    getMonthNames(style: "long" | "short" | "narrow"): string[] {
        // Moment.js doesn't support narrow month names, so we just use short if narrow is requested.
        return style === "long"
            ? this._localeData.longMonths
            : this._localeData.shortMonths;
    }

    getDateNames(): string[] {
        return this._localeData.dates;
    }

    getDayOfWeekNames(style: "long" | "short" | "narrow"): string[] {
        if (style === "long") {
            return this._localeData.longDaysOfWeek;
        }
        if (style === "short") {
            return this._localeData.shortDaysOfWeek;
        }
        return this._localeData.narrowDaysOfWeek;
    }

    getYearName(date: Moment): string {
        return this.clone(date).format("YYYY");
    }

    getFirstDayOfWeek(): number {
        return this._localeData.firstDayOfWeek;
    }

    getNumDaysInMonth(date: Moment): number {
        return this.clone(date).daysInMonth();
    }

    clone(date: Moment): Moment {
        return date.clone().locale(this.locale);
    }

    createDate(year: number, month: number, date: number): Moment {
        if (month < 0 || month > 11) {
            throw Error(
                `Invalid month index "${month}". Month index has to be between 0 and 11.`
            );
        }

        if (date < 1) {
            throw Error(
                `Invalid date "${date}". Date has to be greater than 0.`
            );
        }

        const result = this._createMoment({ year, month, date }).locale(
            this.locale
        );
        if (!result.isValid()) {
            throw Error(
                `Invalid date "${date}" for month with index "${month}".`
            );
        }

        return result;
    }

    today(): Moment {
        // @ts-ignore
        return this._createMoment().locale(this.locale);
    }

    parse(value: any, parseFormat: string | string[]): Moment | null {
        if (value && typeof value === "string") {
            return this._createMoment(value, parseFormat, this.locale);
        }
        return value ? this._createMoment(value).locale(this.locale) : null;
    }

    format(date: Moment, displayFormat: string): string {
        date = this.clone(date);
        if (!this.isValid(date)) {
            throw Error("MomentDateAdapter: Cannot format invalid date.");
        }
        return date.format(displayFormat);
    }

    addCalendarYears(date: Moment, years: number): Moment {
        return this.clone(date).add({ years });
    }

    addCalendarMonths(date: Moment, months: number): Moment {
        return this.clone(date).add({ months });
    }

    addCalendarDays(date: Moment, days: number): Moment {
        return this.clone(date).add({ days });
    }

    toIso8601(date: Moment): string {
        return this.clone(date).format();
    }

    deserialize(value: any): Moment | null {
        let date;
        if (value instanceof Date) {
            date = this._createMoment(value).locale(this.locale);
        } else if (this.isDateInstance(value)) {
            return this.clone(value);
        }
        if (typeof value === "string") {
            if (!value) {
                return null;
            }
            date = this._createMoment(value, moment.ISO_8601).locale(
                this.locale
            );
        }
        if (date && this.isValid(date)) {
            return this._createMoment(date).locale(this.locale);
        }
        return super.deserialize(value);
    }

    isDateInstance(obj: any): boolean {
        return moment.isMoment(obj);
    }

    isValid(date: Moment): boolean {
        return this.clone(date).isValid();
    }

    invalid(): Moment {
        return moment.invalid();
    }

    getHour(date: _moment.Moment): number {
        return date.hours();
    }
    getMinute(date: _moment.Moment): number {
        return date.minutes();
    }
    getSecond(date: _moment.Moment): number {
        return date.seconds();
    }
    setHour(date: _moment.Moment, value: number): void {
        date.hours(value);
    }
    setMinute(date: _moment.Moment, value: number): void {
        date.minutes(value);
    }
    setSecond(date: _moment.Moment, value: number): void {
        date.seconds(value);
    }

    private _createMoment(
        date: MomentInput,
        format?: MomentFormatSpecification,
        locale?: string
    ): Moment {
        const { strict, useUtc }: NgxMatMomentDateAdapterOptions =
            this._options || {};

        return useUtc
            ? moment.utc(date, format, locale, strict)
            : moment(date, format, locale, strict);
    }
}

import { Injectable, EventEmitter } from '@angular/core';

@Injectable({
    providedIn: 'root'
})
export class PubSubService {

    /**
     * Constructor
     */
    constructor() {
    }

    // Event Observable mapping
    public eventObservableMapping$: { [eventName: string]: EventEmitter<any> } = {}; 

    /**
     * publishEvent
     * @param eventName Name of event
     * @param data Data to emit
     */
    public publishEvent(eventName: string, data?: any) {
        if(this.eventObservableMapping$[eventName]) {
            this.eventObservableMapping$[eventName].emit(data);
        }
    }

    /**
     * subscribe
     * @param eventName Name of event
     * @param next Function to run on next
     * @param error Function to run on error
     */
    subscribe(eventName: string, next?: (value: any) => void, error?: (error: any) => any, complete?: () => void) {
        if(!this.eventObservableMapping$[eventName]) {
            this.eventObservableMapping$[eventName] = new EventEmitter();
        }
        return this.eventObservableMapping$[eventName].subscribe(next, error);
    }

}

import { Injectable, EventEmitter } from '@angular/core';
import { HttpClient } from '@angular/common/http';
// import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from '@angular/router';
import { Observable, BehaviorSubject } from 'rxjs';
import { ToastService } from './toast.service';
import { ActivatedRoute, Router } from '@angular/router';
import { BackendService } from './backend.service';
import { PubSubService } from 'app/oc/services/pubsub.service';
import { AuthService } from './auth.service';
import { DialogService } from './dialog.service';
import { ConsoleLoggerService } from './console_logger.service';
import { ReportList } from '../interfaces';
import { HelperService } from './helper.service';
import { saveAs } from 'file-saver';

@Injectable({
    providedIn: 'root'
})
export class ReportService // implements Resolve<any>
{
    // Reports lazy loading
    isLazyLoadingEnabled = true;
    lazyLoadingEntryName: string;

    public cache = {};

    // local data
    private _currentData: ReportList = {
        entryName: "",
        lazyLoaded: false,
        reports: []
    };

    // get current data
    public getCurrentData() {
        return this._currentData;
    }

    // Stream for loaded reports
    public onReportsLoaded: BehaviorSubject<ReportList>;

    // Event Emitter for reload requests
    public reloadRequested: EventEmitter<string> = new EventEmitter();

    // Event Emitter for getting report requests
    public getReportRequested: EventEmitter<string> = new EventEmitter();

    // Event Emitter for clear requests
    public lazyLoadingListening: EventEmitter<any> = new EventEmitter();



    /**
     * Constructor
     *
     * @param {HttpClient} _httpClient
     * @param {BackendService} _backendService
     * @param {ToastService} _toastService
     * @param {DialogService} _dialogService
     */
    constructor(
        private _httpClient: HttpClient,
        private _backendService: BackendService,
        private _toastService: ToastService,
        private _dialogService: DialogService,
        private _console: ConsoleLoggerService

    ) {
        // Set the defaults
        this.onReportsLoaded = new BehaviorSubject({ entryName: "", lazyLoaded: false, reports: [] });

    }

    getReport(entryName: string, company: string, keys: any, alias: string, isForm: boolean, searchKeys: any) {
        let _this = this;
        _this._dialogService.showLoadingDialog("Getting report", "Please wait...");

        _this._backendService.getReport(entryName, company, keys, alias, isForm, searchKeys).subscribe(
            response => {
                _this._console.log(response);
                if (response.result === 'OK') {
                    const url = response.url;
                    _this._httpClient.get(url, { responseType: 'blob' }).subscribe(
                        fileData => {
                            const keysString = Object.keys(keys).map(key => keys[key]).join("_");
                            const entryNameLength = Math.min(entryName.length, 4);
                            const entryNameShort = entryName.substring(0, entryNameLength);
                            // Save the file 
                            saveAs(fileData, `${keysString}_${entryNameShort}_${HelperService.getFormattedShortDate(new Date())}.pdf`);

                            // Close dialog and show success toast
                            _this._dialogService.closeDialog();
                            _this._toastService.showSuccessToast("Report downloaded successfully!");
                        },
                        error => {
                            // Show error snackbar
                            _this._dialogService.closeDialog();
                            _this._toastService.showErrorToast(error);
                        });
                }
                else {
                    // Show error snackbar
                    _this._dialogService.closeDialog();
                    _this._toastService.showErrorToast(response.reason);
                }
            },
            error => {
                // Show error snackbar
                _this._dialogService.closeDialog();
                _this._toastService.showErrorToast(error);
            }
        );
    }

    getReports(entryName: string, company: string, keys: any, isForm: boolean) {
        let _this = this;

        // If alread in cache, return it
        if(_this.cache[entryName]) {
            // Reset stored data
            _this._currentData = _this.cache[entryName];

            // now give results back to the requester
            _this.onReportsLoaded.next(_this._currentData);
        }
        else {
            if (entryName == 'dashboard') {
                // Reset stored data
                _this._currentData = {
                    entryName: entryName,
                    lazyLoaded: _this.isLazyLoadingEnabled,
                    reports: []
                };

                // Save in cache
                _this.cache[entryName] = _this._currentData;

                // now give results back to the requester
                _this.onReportsLoaded.next(_this._currentData);
            }
            else {
                _this._backendService.getReportList(entryName, company, keys, isForm).subscribe(
                    response => {
                        _this._console.log(response);
                        if (response.result === 'OK') {
                            // Store data locally
                            _this._currentData = {
                                entryName: entryName,
                                lazyLoaded: _this.isLazyLoadingEnabled,
                                reports: response.list
                            };

                            // Save in cache
                            _this.cache[entryName] = _this._currentData;

                            // now give results back to the requester
                            _this.onReportsLoaded.next(_this._currentData);
                        }
                        else {
                            // Reset stored data
                            _this._currentData = {
                                entryName: entryName,
                                lazyLoaded: _this.isLazyLoadingEnabled,
                                reports: []
                            };

                            // Save in cache
                            _this.cache[entryName] = _this._currentData;

                            // now give results back to the requester
                            _this.onReportsLoaded.next(_this._currentData);

                            // Show error snackbar
                            _this._toastService.showErrorToast(response.reason);
                        }
                    },
                    error => {
                        // Error occured!
                        _this._dialogService.closeDialog();
                        _this._toastService.showErrorToast("An error occured!", error);

                    }
                );
            }
        }
    }

    requestReload(entryName) {
        let _this = this;

        // Request only if we already don't have the reports for this entryName
        if(_this.cache[entryName]) {
            // Save in cache
            _this.cache[entryName].lazyLoaded = false;
            _this._currentData = _this.cache[entryName];

            // now give results back to the requester
            _this.onReportsLoaded.next(_this._currentData);
        }
        else if (_this._currentData.entryName !== entryName) {
            _this.reloadRequested.emit(entryName);
        }
    }

    requestGetReport(alias) {
        // Request if report with alias exists in current reports list
        if (this._currentData.reports.filter(x => x.alias === alias).length > 0) {
            this.getReportRequested.emit(alias);
        }
    }

    prepareLazyLoad(entryName: string) {
        this.lazyLoadingEntryName = entryName;
        this.lazyLoadingListening.emit(true);
    }

    requestLazyReload() {
        if(this.lazyLoadingEntryName) {
            this.requestReload(this.lazyLoadingEntryName);
        }
    }

}

