import { Injectable, EventEmitter } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { ToastService } from './toast.service';
import { HelperService } from './helper.service';

@Injectable({
    providedIn: 'root'
})
export class TimezoneService {

    private useApi = false;

    private apiInfoUrl: string = 'https://worldtimeapi.org/api/ip';
    public timezoneInfo: any = {
        // abbreviation: null,
        // client_ip: null,
        // datetime: null,
        // day_of_week:1,
        // day_of_year:1,
        // dst: false,
        // dst_from: null,
        // dst_offset: 0,
        // dst_until: null,
        // raw_offset: 0,
        timezone: null,
        // unixtime: 0,
        // utc_datetime: null,
        utc_offset: null,
        // week_number: 0
    };

    /**
     * API Sample response
    {
        abbreviation: "PKT",
        client_ip: "182.178.243.167",
        datetime: "2023-11-23T16:23:26.800194+05:00",
        day_of_week: 4,
        day_of_year: 327,
        dst: false,
        dst_from: null,
        dst_offset: 0,
        dst_until: null,
        raw_offset: 18000,
        timezone: "Asia/Karachi",
        unixtime: 1700738606,
        utc_datetime: "2023-11-23T11:23:26.800194+00:00",
        utc_offset: "+05:00",
        week_number: 47,
    }
    */

    /**
     * Constructor
     *
     */
    constructor(
        private _http: HttpClient,
        private _toastService: ToastService
    ) {
        const _this = this;
        setTimeout(() => _this.getTimezoneInfo(), 2000);
    }

    /**
     * Get Timezone info
     * @returns timezone
     */
    getTimezoneInfo() {
        let _this = this;

        if(_this.useApi) {
            _this._http.get(_this.apiInfoUrl, { observe: 'response' })
            .subscribe(
                result => {
                    _this.timezoneInfo = result.body;
                    localStorage.setItem('timezoneInfo', JSON.stringify(result.body));
                },
                error => {
                    let timezoneInfoLocal = localStorage.getItem('timezoneInfo');
                    if(timezoneInfoLocal && timezoneInfoLocal.length > 10) {
                        _this.timezoneInfo = JSON.parse(timezoneInfoLocal);
                    }
                    else {
                        _this._toastService.showErrorToast(error);
                    }
                }
            );
        }
        else {
            const localOffset = new Date().getTimezoneOffset() * -1;
            const localOffsetAbs = Math.abs(localOffset);
            const hours = localOffsetAbs/60;
            const minutes = localOffsetAbs%60;
            const utc_offset = (localOffset < 0? "-": "+") + HelperService.getTwoDigitText(hours) + ":" + HelperService.getTwoDigitText(minutes);
            const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

            _this.timezoneInfo.utc_offset = utc_offset;
            _this.timezoneInfo.timezone = timezone;
            localStorage.setItem('timezoneInfo', JSON.stringify(_this.timezoneInfo));
        }
    }

}

import { Injectable } from '@angular/core';
import { ToastrService, IndividualConfig, ActiveToast } from 'ngx-toastr';

@Injectable({
    providedIn: 'root'
})
export class ToastService {

    // Examples:
    // this.ToastService.showSuccessToast('Success', 'Yesh! Done.', 2500);
    // this.ToastService.showErrorToast('Error', 'Yesh! Done.', 2500);

    // Private
    private lastLoadingToast: ActiveToast<any> = null;

    private _toastrTheme: Partial<IndividualConfig> = {
        tapToDismiss: true,
        closeButton: false,
        timeOut: 2000,
        extendedTimeOut: 2000,
        easing: 'ease-in',
        easeTime: 300,
        enableHtml: false,
        progressBar: false,
        progressAnimation: 'decreasing',
        toastClass: 'ngx-toastr',
        positionClass: 'toast-top-right',
        titleClass: 'toast-title',
        messageClass: 'toast-message',
        onActivateTick: false
    };

    /**
     * Constructor
     *
     */
    constructor(private toastr: ToastrService) {
    }


    // -----------------------------------------------------------------------------------------------------
    // @ Public methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Set Snackbar Toast Theme
     *
     * @param position
     * @param width
     * @param background
     * @param padding
     * @param showConfirmButton
     * @param toast
     */
    setToastTheme(
        tapToDismiss: true,
        closeButton: false,
        timeOut: 2000,
        extendedTimeOut: 2000,
        easing: 'ease-in',
        easeTime: 300,
        enableHtml: false,
        progressBar: false,
        progressAnimation: 'decreasing',
        toastClass: 'ngx-toastr',
        positionClass: 'toast-top-right',
        titleClass: 'toast-title',
        messageClass: 'toast-message',
        onActivateTick: false): void {

        this._toastrTheme = {
            tapToDismiss: tapToDismiss,
            closeButton: closeButton,
            timeOut: timeOut,
            extendedTimeOut: extendedTimeOut,
            easing: easing,
            easeTime: easeTime,
            enableHtml: enableHtml,
            progressBar: progressBar,
            progressAnimation: progressAnimation,
            toastClass: toastClass,
            positionClass: positionClass,
            titleClass: titleClass,
            messageClass: messageClass,
            onActivateTick: onActivateTick,
        }
    }


    //----------------------------- Toasts -----------------------------------

    /**
     * Show Success Snackbar Toast
     *
     * @param title
     * @param text
     * @param timeOut
     * @param tapToDismiss
     */
    showSuccessToast(title: string, text: string = "", timeOut: number = this._toastrTheme.timeOut, tapToDismiss: boolean = this._toastrTheme.tapToDismiss) {
        this.toastr.success(
            text,
            title,
            {
                timeOut: timeOut,
                tapToDismiss: tapToDismiss
            }
        );
    }

    /**
     * Show Success Snackbar Toast
     *
     * @param title
     * @param text
     * @param timeOut
     * @param tapToDismiss
     */
    showInfoToast(title: string, text: string = "", timeOut: number = this._toastrTheme.timeOut, tapToDismiss: boolean = this._toastrTheme.tapToDismiss) {
        this.toastr.info(
            text,
            title,
            {
                timeOut: timeOut,
                tapToDismiss: tapToDismiss
            }
        );
    }

    /**
     * Show Success Snackbar Toast
     *
     * @param title
     * @param text
     * @param timeOut
     * @param tapToDismiss
     */
    showWarningToast(title: string, text: string = "", timeOut: number = this._toastrTheme.timeOut, tapToDismiss: boolean = this._toastrTheme.tapToDismiss) {
        this.toastr.warning(
            text,
            title,
            {
                timeOut: timeOut,
                tapToDismiss: tapToDismiss
            }
        );
    }

    /**
     * Show Error Snackbar Toast
     *
     * @param title
     * @param text
     * @param timeOut
     * @param tapToDismiss
     */
    showErrorToast(title: string = "An error occured!", text: string = "", timeOut: number = this._toastrTheme.timeOut, tapToDismiss: boolean = this._toastrTheme.tapToDismiss) {
        this.toastr.error(
            text,
            title,
            {
                timeOut: timeOut,
                tapToDismiss: tapToDismiss,
                progressBar: true,
                progressAnimation: this._toastrTheme.progressAnimation
            }
        );
    }

    /**
     * Show Loading Snackbar Toast
     *
     * @param title
     * @param text
     * @returns toastId
     */
     showLoadingToast(title: string, text) {
        if(this.lastLoadingToast) {
            this.hideLoadingToast(this.lastLoadingToast);
        }

        this.lastLoadingToast = this.toastr.info(
            text,
            title,
            {
                progressBar: true,
                progressAnimation: 'increasing',
                //timeOut: 5 * 60 * 1000,
                disableTimeOut: true,
                tapToDismiss: false,
                closeButton: true
            }
        );

        return this.lastLoadingToast;
    }

    /**
     * Hide Loading Snackbar Toast
     *
     * @param toast
     */
     hideLoadingToast(toast: ActiveToast<any>) {
        if (this.lastLoadingToast == toast) {
            this.toastr.remove(this.lastLoadingToast.toastId);
            this.lastLoadingToast = null;
        }
        else {
            this.toastr.remove(toast.toastId);
        }
    }




}

import { Injectable } from '@angular/core';
import { UntypedFormGroup, Validators } from '@angular/forms';

@Injectable({
    providedIn: 'root'
})
export class ValidationsService {


    /**
     * Constructor
     *
     */
    constructor() {
    }


    /**
     * Check and set input to required if required validation exists
     * @param validations
     * @returns required: boolean
     */
    public static checkIfRequired(validations) {
        let required = false;
        if (validations != null && validations.length > 0) {
            validations.forEach(validation => {
                if (validation.name === 'required') {
                    required = true;
                }
            });
        }
        return required;
    }

    /**
     * Bind validations
     * @param validations
     * @returns Validators
     */
    public static bindValidations(validations: any) {
        if (validations.length > 0) {
            const validList = [];
            validations.forEach(valid => {
                if (valid.name === 'minlength') {
                    validList.push(Validators.minLength(valid.value));
                }
                else if (valid.name === 'maxlength') {
                    validList.push(Validators.maxLength(valid.value));
                }
                else if (valid.name === 'min') {
                    validList.push(Validators.min(valid.value));
                }
                else if (valid.name === 'max') {
                    validList.push(Validators.max(valid.value));
                }
                else {
                    validList.push(valid.validator);
                }
            });
            return Validators.compose(validList);
        }
        return null;
    }

    /**
     * Process Form Validations
     * @param validations
     * @returns Validators
     */
    public static processFormValidations(validations) {
        for (const validator of validations) {
            if (validator['name'] === 'minlength') {
                validator['validator'] = Validators.minLength(validator['value']);
            }
            else if (validator['name'] === 'maxlength') {
                validator['validator'] = Validators.maxLength(validator['value']);
            }
            else if (validator['name'] === 'min') {
                validator['validator'] = Validators.min(validator['value']);
            }
            else if (validator['name'] === 'max') {
                validator['validator'] = Validators.max(validator['value']);
            }
            else if (validator['name'] === 'required') {
                validator['validator'] = Validators.required;
            }
            else if (validator['name'] === 'pattern') {
                validator['validator'] = Validators.pattern(validator['validator']);
            }
        }
        return validations;
    }

    /**
     * Validate all form fields
     * @param formGroup
     */
    public static validateAllFormFields(formGroup: UntypedFormGroup) {
        Object.keys(formGroup.controls).forEach(field => {
            const control = formGroup.get(field);
            control.markAsTouched({ onlySelf: true });
        });
    }

}

