import { Injectable } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivate, RouterStateSnapshot } from '@angular/router';
import { Store } from '@ngrx/store';

import { Observable, forkJoin, of } from 'rxjs';
import { map, switchMap, catchError, tap, take, filter } from 'rxjs/operators';

import { MailAppState } from 'app/main/apps/mail-ngrx/store/reducers';
import * as fromStore from 'app/main/apps/mail-ngrx/store';
import { getFiltersLoaded, getFoldersLoaded, getLabelsLoaded, getMailsLoaded } from 'app/main/apps/mail-ngrx/store/selectors';
import { getRouterState } from 'app/store/reducers';

@Injectable()
export class ResolveGuard implements CanActivate
{
    routerState: any;

    /**
     * Constructor
     *
     * @param {Store<MailAppState>} _store
     */
    constructor(
        private _store: Store<MailAppState>
    )
    {
        this._store.select(getRouterState).subscribe(routerState => {
            if ( routerState )
            {
                this.routerState = routerState.state;
            }
        });
    }

    /**
     * Can activate
     *
     * @param {ActivatedRouteSnapshot} route
     * @param {RouterStateSnapshot} state
     * @returns {Observable<boolean>}
     */
    canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<boolean>
    {
        return this.checkStore().pipe(
            switchMap(() => of(true)),
            catchError(() => of(false))
        );
    }

    /**
     * Check store
     *
     * @returns {Observable<any>}
     */
    checkStore(): Observable<any>
    {
        return forkJoin(
            this.getFolders(),
            this.getFilters(),
            this.getLabels()
        )
            .pipe(
                filter(([foldersLoaded, filtersLoaded, labelsLoaded]) => !!(foldersLoaded && filtersLoaded && labelsLoaded)),
                take(1),
                switchMap(() =>
                    this.getMails()
                ),
                take(1),
                map(() => this._store.dispatch(new fromStore.SetCurrentMail(this.routerState.params.mailId)))
            );
    }

    /**
     * Get folders
     *
     * @returns {Observable<any>}
     */
    getFolders(): any
    {
        return this._store.select(getFoldersLoaded)
                   .pipe(
                       tap(loaded => {
                           if ( !loaded )
                           {
                               this._store.dispatch(new fromStore.GetFolders([]));
                           }
                       }),
                       filter(loaded => loaded),
                       take(1)
                   );
    }

    /**
     * Get Filters
     *
     * @returns {Observable<any>}
     */
    getFilters(): any
    {
        return this._store.select(getFiltersLoaded)
                   .pipe(
                       tap(loaded => {
                           if ( !loaded )
                           {
                               this._store.dispatch(new fromStore.GetFilters([]));
                           }
                       }),
                       filter(loaded => loaded),
                       take(1)
                   );
    }

    /**
     * Get Labels
     * @returns {Observable<any>}
     */
    getLabels(): any
    {
        return this._store.select(getLabelsLoaded)
                   .pipe(
                       tap(loaded => {
                           if ( !loaded )
                           {
                               this._store.dispatch(new fromStore.GetLabels([]));
                           }
                       }),
                       filter(loaded => loaded),
                       take(1)
                   );
    }

    /**
     * Get Mails
     *
     * @returns {Observable<any>}
     */
    getMails(): any
    {
        return this._store.select(getMailsLoaded)
                   .pipe(
                       tap((loaded: any) => {

                           if ( !this.routerState.params[loaded.id] || this.routerState.params[loaded.id] !== loaded.value )
                           {
                               this._store.dispatch(new fromStore.GetMails());
                               this._store.dispatch(new fromStore.SetSearchText(''));
                               this._store.dispatch(new fromStore.DeselectAllMails());
                           }
                       }),
                       filter((loaded: any) => {
                           return this.routerState.params[loaded.id] && this.routerState.params[loaded.id] === loaded.value;
                       }),
                       take(1)
                   );
    }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { ActivatedRouteSnapshot, Resolve, RouterStateSnapshot } from '@angular/router';
import { Observable, BehaviorSubject } from 'rxjs';

@Injectable()
export class ScrumboardService implements Resolve<any>
{
    boards: any[];
    routeParams: any;
    board: any;

    onBoardsChanged: BehaviorSubject<any>;
    onBoardChanged: BehaviorSubject<any>;

    /**
     * Constructor
     *
     * @param {HttpClient} _httpClient
     */
    constructor(
        private _httpClient: HttpClient
    )
    {
        // Set the defaults
        this.onBoardsChanged = new BehaviorSubject([]);
        this.onBoardChanged = new BehaviorSubject([]);
    }

    /**
     * Resolver
     *
     * @param {ActivatedRouteSnapshot} route
     * @param {RouterStateSnapshot} state
     * @returns {Observable<any> | Promise<any> | any}
     */
    resolve(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): Observable<any> | Promise<any> | any
    {
        this.routeParams = route.params;

        return new Promise((resolve, reject) => {
            Promise.all([
                this.getBoards()
            ]).then(
                (x: any) => {
                    resolve(x);
                },
                reject
            );
        });
    }

    /**
     * Get boards
     *
     * @returns {Promise<any>}
     */
    getBoards(): Promise<any>
    {
        return new Promise((resolve, reject) => {
            this._httpClient.get('api/scrumboard-boards')
                .subscribe((response: any) => {
                    this.boards = response;
                    this.onBoardsChanged.next(this.boards);
                    resolve(this.boards);
                }, reject);
        });
    }

    /**
     * Get board
     *
     * @param boardId
     * @returns {Promise<any>}
     */
    getBoard(boardId): Promise<any>
    {
        return new Promise((resolve, reject) => {
            this._httpClient.get('api/scrumboard-boards/' + boardId)
                .subscribe((response: any) => {
                    this.board = response;
                    this.onBoardChanged.next(this.board);
                    resolve(this.board);
                }, reject);
        });
    }

    /**
     * Add card
     *
     * @param listId
     * @param newCard
     * @returns {Promise<any>}
     */
    addCard(listId, newCard): Promise<any>
    {
        this.board.lists.map((list) => {
            if ( list.id === listId )
            {
                return list.idCards.push(newCard.id);
            }
        });

        this.board.cards.push(newCard);

        return this.updateBoard();
    }

    /**
     * Add list
     *
     * @param newList
     * @returns {Promise<any>}
     */
    addList(newList): Promise<any>
    {
        this.board.lists.push(newList);

        return this.updateBoard();
    }

    /**
     * Remove list
     *
     * @param listId
     * @returns {Promise<any>}
     */
    removeList(listId): Promise<any>
    {
        const list = this.board.lists.find((_list) => {
            return _list.id === listId;
        });

        for ( const cardId of list.idCards )
        {
            this.removeCard(cardId);
        }

        const index = this.board.lists.indexOf(list);

        this.board.lists.splice(index, 1);

        return this.updateBoard();
    }

    /**
     * Remove card
     *
     * @param cardId
     * @param listId
     */
    removeCard(cardId, listId?): void
    {
        const card = this.board.cards.find((_card) => {
            return _card.id === cardId;
        });

        if ( listId )
        {
            const list = this.board.lists.find((_list) => {
                return listId === _list.id;
            });
            list.idCards.splice(list.idCards.indexOf(cardId), 1);
        }

        this.board.cards.splice(this.board.cards.indexOf(card), 1);

        this.updateBoard();
    }

    /**
     * Update board
     *
     * @returns {Promise<any>}
     */
    updateBoard(): Promise<any>
    {
        return new Promise((resolve, reject) => {
            this._httpClient.post('api/scrumboard-boards/' + this.board.id, this.board)
                .subscribe(response => {
                    this.onBoardChanged.next(this.board);
                    resolve(this.board);
                }, reject);
        });
    }

    /**
     * Update card
     *
     * @param newCard
     */
    updateCard(newCard): void
    {
        this.board.cards.map((_card) => {
            if ( _card.id === newCard.id )
            {
                return newCard;
            }
        });

        this.updateBoard();
    }

    /**
     * Create new board
     *
     * @param board
     * @returns {Promise<any>}
     */
    createNewBoard(board): Promise<any>
    {
        return new Promise((resolve, reject) => {
            this._httpClient.post('api/scrumboard-boards/' + board.id, board)
                .subscribe(response => {
                    resolve(board);
                }, reject);
        });
    }
}

