                else {
                    // Show error snackbar
                    _this.isSaving = false;
                    _this._toastService.showErrorToast(responseCheck.reason);
                }
            }
            else {
                // Show error snackbar
                _this.isSaving = false;
                _this._toastService.showErrorToast(responseURL.reason);
            }
        }
        catch (e) {
            _this.isSaving = false;
            _this._toastService.showErrorToast(e);
        }
