    getValue(val: any) {
        if (val !== null && val !== undefined) {
            if (typeof val === 'object' && !Array.isArray(val)) {
                if (val.id !== null && val.id !== undefined) {
                    if (typeof val.id === 'object' && !Array.isArray(val.id)) {
                        return val.id.id;
                    }
                    else {
                        return val.id;
                    }
                }
            }
            else {
                return val;
            }
        }
        return null;
    }

